#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "correlation.h"


/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   The implementation below reorganizes loops to improve data locality
   and cache utilization while preserving the original floating-point
   computation order for each scalar accumulation:

   - Means and variances for each column are still reduced in strictly
     increasing i-order, but the data traversals are done row-major.
   - The subtraction used for centering is fused with the variance
     accumulation so each (data[i][j] - mean[j]) is computed once.
   - sqrt(float_n) and the per-column scaling factors are precomputed.
   - The correlation matrix is formed by iterating over rows of the
     normalized data, improving spatial locality in both data[] and
     corr[] without changing the reduction order over k for any entry
     corr[i][j].
*/
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Local restrict-qualified aliases help the compiler with
     alias analysis and vectorization, without changing semantics. */
  DATA_TYPE (* restrict data_)[m]   = data;
  DATA_TYPE (* restrict corr_)[m]   = corr;
  DATA_TYPE * restrict mean_        = mean;
  DATA_TYPE * restrict stddev_      = stddev;

#pragma scop
  /* ----------------------------------------
   * Step 1: compute column means.
   *
   * Original code:
   *   for j: mean[j] = 0; for i: mean[j] += data[i][j];
   *
   * We keep, for each column j, the same recurrence:
   *   mean_j^{i+1} = mean_j^{i} + data[i][j]
   * in the same i-order, but traverse data in row-major order in
   * the accumulation loop for better cache behavior.
   * ---------------------------------------- */

  /* Initialize means. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate sums row by row. */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean_[j] += data_[i][j];

  /* Divide by float_n to obtain the mean. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;


  /* ----------------------------------------
   * Step 2: compute variance (stddev^2) and center data.
   *
   * Original code:
   *   for j:
   *     stddev[j] = 0;
   *     for i:
   *       tmp = data[i][j] - mean[j];
   *       stddev[j] += tmp * tmp;
   *
   *   (data is still unmodified here; centering happens later.)
   *
   * Here we:
   *   - zero all stddev[j],
   *   - traverse data row-major,
   *   - compute diff = data[i][j] - mean[j],
   *   - store diff back into data[i][j] (centering),
   *   - accumulate diff*diff into stddev[j].
   *
   * For each column j, the reduction over i uses the same order
   * as the original (i = 0..N-1), ensuring bit-identical results
   * for stddev[j] while improving locality and avoiding a second
   * evaluation of (data[i][j] - mean[j]) later.
   * ---------------------------------------- */

  for (j = 0; j < _PB_M; j++)
    stddev_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        DATA_TYPE diff = data_[i][j] - mean_[j];
        data_[i][j] = diff;           /* Center the data. */
        stddev_[j] += diff * diff;    /* Accumulate squared deviation. */
      }


  /* ----------------------------------------
   * Step 3: finalize standard deviations.
   *
   * This is identical to the original kernel but split out into a
   * separate loop over j after the variance accumulation above.
   * ---------------------------------------- */

  for (j = 0; j < _PB_M; j++)
    {
      stddev_[j] /= float_n;
      stddev_[j] = SQRT_FUN(stddev_[j]);

      /* Handle near-zero std. dev. values to avoid division by zero. */
      stddev_[j] = stddev_[j] <= eps ? SCALAR_VAL(1.0) : stddev_[j];
    }


  /* ----------------------------------------
   * Step 4: scale centered data to unit variance.
   *
   * Original code:
   *   for i:
   *     for j:
   *       data[i][j] -= mean[j];
   *       data[i][j] /= sqrt(float_n) * stddev[j];
   *
   * With Step 2 we already performed the subtraction and stored
   * data[i][j] = (original_data - mean[j]). Here we only need the
   * scaling by sqrt(float_n) * stddev[j].
   *
   * We precompute:
   *   sqrt_float_n = sqrt(float_n)
   *   scale[j]     = sqrt_float_n * stddev[j]
   *
   * and then divide by scale[j]. The product sqrt_float_n*stddev[j]
   * is identical for every element in column j, so computing it
   * once per column is numerically equivalent to recomputing it at
   * every element, but much cheaper.
   * ---------------------------------------- */

  const DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);
  DATA_TYPE scale[_PB_M];

  for (j = 0; j < _PB_M; j++)
    scale[j] = sqrt_float_n * stddev_[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data_[i][j] /= scale[j];


  /* ----------------------------------------
   * Step 5: compute the m x m correlation matrix.
   *
   * Original code:
   *   for i = 0..M-2:
   *     corr[i][i] = 1;
   *     for j = i+1..M-1:
   *       corr[i][j] = 0;
   *       for k = 0..N-1:
   *         corr[i][j] += data[k][i] * data[k][j];
   *       corr[j][i] = corr[i][j];
   *   corr[M-1][M-1] = 1;
   *
   * That is, for each (i,j) with i < j we perform the reduction:
   *   corr[i][j] = sum_{k=0}^{N-1} data[k][i] * data[k][j]
   *
   * We reorganize the loops so that we:
   *   1. Initialize the upper triangle corr[i][j] for i < j to 0.
   *   2. Accumulate over k (rows) first:
   *        for k:
   *          for i:
   *            for j > i:
   *              corr[i][j] += data[k][i] * data[k][j];
   *   3. Set diag to 1.0 and copy the upper triangle to the lower.
   *
   * For every fixed (i,j) with i < j, corr[i][j] still sees
   * contributions in the exact same order of k = 0..N-1, so the
   * floating-point reduction sequence for each entry is unchanged.
   * Traversing k outermost gives better reuse of the contiguous row
   * data[k][*] and improves cache locality.
   * ---------------------------------------- */

  /* Initialize upper triangle (i < j) to zero. */
  for (i = 0; i < _PB_M; i++)
    for (j = i + 1; j < _PB_M; j++)
      corr_[i][j] = SCALAR_VAL(0.0);

  /* Accumulate correlation from normalized rows. */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE * restrict row = data_[k];
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE x = row[i];
          for (j = i + 1; j < _PB_M; j++)
            corr_[i][j] += x * row[j];
        }
    }

  /* Set diagonal to 1.0 and fill the lower triangle by symmetry. */
  for (i = 0; i < _PB_M; i++)
    {
      corr_[i][i] = SCALAR_VAL(1.0);
      for (j = i + 1; j < _PB_M; j++)
        corr_[j][i] = corr_[i][j];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(stddev);

  return 0;
}
