   * still performed in increasing i order (0,1,...,_PB_N-1), so the
   * floating‑point semantics for each mean[j] are preserved.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_row = &data[i][0];
    for (j = 0; j < _PB_M; j++)
      mean[j] += data_row[j];
  }

  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;


  /* --------------------------------------------------------------------
   * 2. Compute column standard deviations
   *
   * As for the means, we switch to a row-major traversal for better
   * spatial locality while preserving the per-column accumulation order.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_row = &data[i][0];
    for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE diff = data_row[j] - mean[j];
      stddev[j] += diff * diff;
    }
  }

  for (j = 0; j < _PB_M; j++)
  {
    stddev[j] /= float_n;
    stddev[j] = SQRT_FUN(stddev[j]);
    /* Handle near-zero std. dev. values to avoid division by zero. */
    stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
  }

  /* --------------------------------------------------------------------
   * 3. Precompute normalization denominators
   *
   * The original code normalized with:
   *   data[i][j] /= SQRT_FUN(float_n) * stddev[j];
   *
   * SQRT_FUN(float_n) is invariant and stddev[j] is now fixed for each
   * column.  We compute:
   *   sqrt_float_n = SQRT_FUN(float_n);
   *   stddev[j]    = sqrt_float_n * stddev[j];
   *
   * so that the subsequent division uses exactly the same denominator
   * as in the original code, but we compute it once per column instead
   * of once per element.
   * ------------------------------------------------------------------ */
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);
  for (j = 0; j < _PB_M; j++)
    stddev[j] *= sqrt_float_n;


  /* --------------------------------------------------------------------
   * 4. Center and reduce the column vectors
   *
   * We again traverse the matrix row-by-row for improved locality.
   * The normalization expression is algebraically identical to the
   * original one:
   *
   *   (data[i][j] - mean[j]) / (SQRT_FUN(float_n) * stddev_original[j])
   *
   * since we have replaced stddev[j] by
   *   stddev[j] = SQRT_FUN(float_n) * stddev_original[j].
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_row = &data[i][0];
    for (j = 0; j < _PB_M; j++)
    {
      data_row[j] -= mean[j];
      data_row[j] /= stddev[j];
    }
  }


  /* --------------------------------------------------------------------
   * 5. Calculate the m * m correlation matrix
   *
   * We keep the original loop structure over (i, j, k) so that for each
   * pair (i, j) the accumulation over k proceeds in exactly the same
   * order as before, preserving numerical semantics.
   *
   * Optimization:
   *   - Use a scalar accumulator 'corr_ij' to keep the running sum in
   *     a register, writing corr[i][j] only once per pair.
   *   - Parallelize the outer loop over i with OpenMP.  Each iteration
   *     with a given i writes to a disjoint set of matrix elements:
   *       * corr[i][i]
   *       * corr[i][j] and corr[j][i] for j > i
   *     so there are no data races between different i-iterations.
   *
   * The 'if' clause avoids OpenMP overhead for very small matrices when
   * compiled with -fopenmp; without OpenMP, this pragma is ignored.
   * ------------------------------------------------------------------ */
#pragma omp parallel for private(j,k) schedule(static) if (_PB_M > 32)
  for (i = 0; i < _PB_M-1; i++)
  {
    corr[i][i] = SCALAR_VAL(1.0);

    for (j = i+1; j < _PB_M; j++)
    {
      DATA_TYPE corr_ij = SCALAR_VAL(0.0);

      for (k = 0; k < _PB_N; k++)
        corr_ij += (data[k][i] * data[k][j]);

      corr[i][j] = corr_ij;
      corr[j][i] = corr_ij;
    }
  }

  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);

#pragma endscop

}


int main(int argc, char** argv)
{
