void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
                 DATA_TYPE float_n,
                 DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
                 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
                 DATA_TYPE POLYBENCH_1D(mean,M,m),
                 DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Aliases with explicit restrict to help the optimizer.
     They point to the same storage as the original arrays. */
  DATA_TYPE * __restrict mean_   = &mean[0];
  DATA_TYPE * __restrict stddev_ = &stddev[0];

  /* Precompute sqrt(float_n) once: reused many times. */
  const DATA_TYPE sqrt_float_n       = SQRT_FUN(float_n);
  const DATA_TYPE inv_sqrt_float_n   = SCALAR_VAL(1.0) / sqrt_float_n;

  /* Temporary column-wise normalization factors:
       norm_factor[j] = 1 / (sqrt(float_n) * stddev[j])
     used in the centering/reduction phase so that the inner loop
     performs a multiplication instead of a division.  This does NOT
     change the mathematical result of the kernel. */
  DATA_TYPE norm_factor[_PB_M];

#pragma scop
  /* --------------------------------------------------------------------
   * 1. Compute column means.
   *
   * Original code:
   *   for (j) {
   *     mean[j] = 0;
   *     for (i) mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *   }
   *
   * We keep the sequence of operations per mean[j] (sum over i in
   * increasing order), but reorder the traversal to be row-major
   * (i outermost, j innermost) to improve cache locality.
   * ------------------------------------------------------------------ */

  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_i = data[i];
    for (j = 0; j < _PB_M; j++)
      mean_[j] += data_i[j];
  }

  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;

