   * 2. Compute column standard deviations.
   *
   * Again we traverse data row-major for better locality.  For each
   * column j we accumulate (data[i][j] - mean[j])^2 over i, in the
   * same order as in the original code.
   * ------------------------------------------------------------------ */

  for (j = 0; j < _PB_M; j++)
    stddev_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_i = data[i];
    for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE diff = data_i[j] - mean_[j];
      stddev_[j] += diff * diff;
    }
