   * 3. Precompute normalization factors.
   *
   *   norm_factor[j] = 1 / (sqrt(float_n) * stddev[j])
   *
   * This lets the centering/reduction step use a single multiply
   * per element instead of a divide, while leaving stddev[] itself
   * unchanged (so the externally observable contents of stddev[]
   * remain identical to the original kernel).
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; j++)
    norm_factor[j] = inv_sqrt_float_n / stddev_[j];

  /* --------------------------------------------------------------------
   * 4. Center and reduce the column vectors.
   *
   * Original:
   *   for (i)
   *     for (j) {
   *       data[i][j] -= mean[j];
   *       data[i][j] /= sqrt(float_n) * stddev[j];
   *     }
   *
   * We compute the same value as:
   *   data[i][j] = (data[i][j] - mean[j]) * norm_factor[j];
   *
   * The loop is parallelized over rows; each (i,j) element is updated
   * exactly once, so this is thread-safe.
   * ------------------------------------------------------------------ */

#pragma omp parallel for default(none) shared(data, mean_, norm_factor) \
                        private(i, j) schedule(static)
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict data_i = data[i];
    for (j = 0; j < _PB_M; j++)
      data_i[j] = (data_i[j] - mean_[j]) * norm_factor[j];
  }

