   * Original code computed each corr[i][j] as a dot product over k
   * with loops (i,j,k) and column-wise (strided) accesses to data.
   *
   * Here we reorganize the computation as:
   *
   *   corr[i][j] = sum_k data[k][i] * data[k][j], i < j
   *
   * implemented as:
   *
   *   initialize corr to 0;
   *   for k in 0..N-1:
   *     row_k = data[k];
   *     for i in 0..M-2:
   *       val_i = row_k[i];
   *       for j in i+1..M-1:
   *         corr[i][j] += val_i * row_k[j];
   *
   * This traverses 'data' by rows (row_k[j] is accessed with unit
   * stride) and greatly improves cache locality.  For each (i,j),
   * the sequence of additions over k is still in increasing k order,
   * so the per-entry floating-point reduction order is preserved.
   *
   * We parallelize across the i-loop for each fixed k using OpenMP:
   *   - The outer k-loop is executed by all threads in lock-step.
   *   - For each k, the i-loop is split among threads (#pragma omp for),
   *     and each (i,j) pair is updated by exactly one thread.
   *   - The implicit barrier at the end of the omp for ensures that
   *     updates from different k values are serialized, so there are
   *     no data races on corr[][].
   *
   * We only compute the upper triangle (i < j).  The diagonal is set
   * to 1.0 at the end, and the lower triangle is filled by symmetry.
   * ------------------------------------------------------------------ */

  /* Initialize full matrix to 0 so we can accumulate into corr[i][j]. */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_M; j++)
      corr[i][j] = SCALAR_VAL(0.0);

#pragma omp parallel default(none) shared(data, corr) private(i, j, k)
  {
    for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE * __restrict row_k = data[k];

      /* Distribute the i-loop across threads for this fixed k. */
#pragma omp for schedule(static)
      for (i = 0; i < _PB_M - 1; i++)
      {
        DATA_TYPE * __restrict corr_i = corr[i];
        const DATA_TYPE val_i = row_k[i];

        /* j loop walks along the row of 'corr' and 'row_k' contiguously. */
        for (j = i + 1; j < _PB_M; j++)
          corr_i[j] += val_i * row_k[j];
      }
    }
  }

  /* Set diagonal elements to exactly 1.0, just like the original code. */
  for (i = 0; i < _PB_M; i++)
    corr[i][i] = SCALAR_VAL(1.0);

  /* Enforce symmetry: corr[j][i] = corr[i][j] for j > i. */
  for (i = 0; i < _PB_M; i++)
    for (j = i + 1; j < _PB_M; j++)
      corr[j][i] = corr[i][j];
#pragma endscop
}


