  DATA_TYPE * restrict stddev_    = stddev;

  /* Precomputed scalar factors reused across multiple loops. */
  const DATA_TYPE inv_float_n       = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE sqrt_float_n      = SQRT_FUN(float_n);
  const DATA_TYPE inv_sqrt_float_n  = SCALAR_VAL(1.0) / sqrt_float_n;

  /* Temporary array for per-column scaling factors:
       scale[j] = 1 / (sqrt(float_n) * stddev[j])
     This converts the normalization division into a multiplication.
     Additional memory is O(m), well within the +50% limit. */
  DATA_TYPE scale[m];

#pragma scop
  /* 1. Compute column means.
     We accumulate row by row (i outer, j inner) so that accesses to
     `data` are contiguous in memory. */

