  for (j = 0; j < pb_m; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate sums row-wise. */
  for (i = 0; i < pb_n; i++)
    {
      DATA_TYPE * restrict data_i = data_[i];
      for (j = 0; j < pb_m; j++)
        mean_[j] += data_i[j];
    }

