     is updated row-wise for contiguous memory access. */

#pragma omp parallel for private(j) schedule(static) if (pb_n * pb_m >= 32768)
  for (i = 0; i < pb_n; i++)
    {
      DATA_TYPE * restrict data_i = data_[i];
      for (j = 0; j < pb_m; j++)
        {
          DATA_TYPE centered = data_i[j] - mean_[j];
          data_i[j] = centered * scale[j];
        }
    }


